import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2020-07-30","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-07-30","date":"2020-07-30T00:00:00.000Z","updated":"2020-07-31T00:00:00.000Z","tags":["Ceph","Distributed Storage","Performance Optimization","BlueStore","MDS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-07-30.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-07-30.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Performance_Meeting_2020-07-30.md"};function o(n,e,h,s,d,p){return i(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph性能会议于2020年7月30日举行，由于正值夏季，会议进度相对较慢。会议主要回顾了近期Ceph项目的开发进展，重点讨论了RGW（RADOS Gateway）和MDS（Metadata Server）的改进。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>RGW改进</strong>：</p><ul><li>Eric提交了一个PR，旨在提高RGW有序列表映射的效率，避免第二次遍历列表。</li><li>另一个PR涉及d3n缓存的上游更改，目前正在审查和测试中。</li></ul></li><li><p><strong>MDS改进</strong>：</p><ul><li>Majiang Ping提交了两个与BlueStore相关的PR，涉及小规模的改进。</li><li>一个修复了在大量子树情况下的缓存修剪问题的MDS PR已合并。</li><li>另一个PR改进了ceph-adm工具，提升了OSD的并行创建性能。</li></ul></li><li><p><strong>性能优化</strong>：</p><ul><li>Majiang Peng提交了一个PR，涉及启用RocksDB管道，可能带来性能提升。</li><li>Radek和Mark正在研究MDS中的缓冲列表和环形缓冲区，以减少CPU使用和内存分配成本。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续审查和测试所有新的和更新的PR。</li><li>进一步研究和优化MDS中的缓冲列表和环形缓冲区，以减少CPU和内存的使用。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成所有PR的审查和测试，确保代码质量和性能。</li><li>继续研究和优化MDS中的缓冲列表和环形缓冲区，目标是提高编码和解码的效率，而不需要改变现有的编码解码框架。</li><li>探索和评估更动态的内存分配策略，特别是在小规模追加操作中的应用。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了缓冲列表在多线程环境下的使用情况，以及如何减少原子操作的开销。</li><li>分享了性能测试的结果和分析，强调了在实际应用中可能存在的性能差异。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了持续改进Ceph项目的重要性，特别是在性能优化和代码质量方面。团队将继续努力，以实现长期目标，即在不改变现有编码解码框架的情况下，提高MDS的效率。</p><p>本次会议纪要由专业的存储领域分布式存储Ceph研发人员和视频会议字幕总结人员共同完成，确保了内容的准确性和专业性。</p>',14)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
